corrected_code:
@app.put('/api/address/{address_id}')
def update_address(address_id: int, payload: AddressSchema, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):
    address = db.query(Address).filter(Address.id == address_id, Address.user_id == current_user.id).first()
    if not address:
        raise HTTPException(status_code=403, detail="Forbidden")
    address.street = payload.street
    db.commit()
    return address
